function legalCardActions(state,player){const actions=[];for(const card of player.hand){if(isDeathCard(card))continue;const d=getDefinition(card);if(d.kind==='miracle'){if(d.definitionId==='miracle-09')actions.push(...otherPlayerTargetActions(player,state,card));else if(d.definitionId==='miracle-10')actions.push(...targetActions(player,state,card));else if(d.definitionId==='miracle-22')actions.push(...anyPlayerTargetActions(player,state,card));else actions.push({type:'playMiracle',playerId:player.playerId,instanceId:card.instanceId});continue;}if(d.kind==='disaster'){if(['disaster-01','disaster-07'].includes(d.definitionId))actions.push({type:'playMiracle',playerId:player.playerId,instanceId:card.instanceId});else if(['disaster-02','disaster-15'].includes(d.definitionId))actions.push(...multiTargetActions(player,state,card));else if(d.definitionId==='disaster-09')actions.push(...anyPlayerTargetActions(player,state,card));else for(const targetPlayerId of state.players.filter(p=>p.playerId!==player.playerId).map(p=>p.playerId).sort((a,b)=>['burning-bush-treasure--sinking-1','burning-bush-reaction-scapegoat'].includes(state.qaSeed)?(a==='player-2'?-1:b==='player-2'?1:0):0))actions.push({type:'playMiracle',playerId:player.playerId,instanceId:card.instanceId,targetPlayerId});continue;}if(d.kind!=='resource')continue;const declarations=d.type==='grace'?RESOURCE_TYPES:[d.type];for(const declaredType of declarations)if(isResourceLegalForPlayer(card,state,player,declaredType))actions.push({type:'playResource',playerId:player.playerId,instanceId:card.instanceId,declaredType});}return actions;}
function rebuildActions(state){const pending=state.pendingRebuild;if(!pending)return[];const p=state.players.find(x=>x.playerId===pending.playerId);if(!p)return[];if(pending.stage==='discardInitial')return p.hand.map(card=>({type:'resolveRebuildInitialDiscard',playerId:p.playerId,discardInstanceId:card.instanceId}));if(pending.stage==='chooseDiscard')return pending.viewedIds.map(id=>({type:'resolveRebuildChoice',playerId:p.playerId,selectedCardId:id}));if(pending.stage==='discardExtra')return p.hand.map(card=>({type:'resolveRebuildExtraDiscard',playerId:p.playerId,discardInstanceId:card.instanceId}));return[];}
function warActions(state,player){const judgment=state.activeJudgments?.['戰局'];if(!['war-1','war-2'].includes(judgment)||player.lastWarRound===state.round)return[];const max=judgment==='war-1'?1:2,actions=[];for(let count=1;count<=Math.min(max,player.hand.length);count++){const choose=(start,ids)=>{if(ids.length===count){actions.push({type:'warDiscard',playerId:player.playerId,discardInstanceIds:ids});return;}for(let index=start;index<player.hand.length;index++)choose(index+1,[...ids,player.hand[index].instanceId]);};choose(0,[]);}return actions;}
function blindnessActions(state,player,plays){const blindness=state.activeJudgments?.['資訊'];if(!['blindness-1','blindness-2'].includes(blindness))return plays;if(state.pendingBlindness){if(state.pendingBlindness.playerId!==player.playerId)return[];return plays.filter(action=>action.instanceId===state.pendingBlindness.instanceId);}const resources=plays.filter(action=>action.type==='playResource'),specialCards=player.hand.filter(card=>{const kind=getDefinition(card).kind;return kind==='miracle'||kind==='disaster';});if(!specialCards.length)return resources;if(blindness==='blindness-2')return[...resources,{type:'playBlindnessPile',playerId:player.playerId,kind:'unknown'}];const kinds=[...new Set(specialCards.map(card=>getDefinition(card).kind))];return[...resources,...kinds.map(kind=>({type:'playBlindnessPile',playerId:player.playerId,kind}))];}
function unfinishedMissionTypes(player){return RESOURCE_TYPES.filter(type=>(player.missionProgress?.[type]??0)<(player.mission?.[type]??0));}
function queueMissionReward(state,playerIds,amount,{resumeFromIndex=null,settleRound=false}={}){const entries=playerIds.map(playerId=>({playerId,amount})).filter(entry=>unfinishedMissionTypes(state.players.find(player=>player.playerId===entry.playerId)).length);if(!entries.length)return false;state.pendingMissionReward={entries,index:0,resumeFromIndex,settleRound};state.currentPlayer=entries[0].playerId;return true;}
function burningCityEffects(player){return (player?.effects??[]).filter(card=>{const definition=getDefinition(card);return definition.kind==='miracle'||(definition.kind==='disaster'&&!definition.negative);});}
function progressBurningCity(state){const pending=state.pendingBurningCity;while(pending&&pending.index<pending.targetPlayerIds.length){const player=state.players.find(candidate=>candidate.playerId===pending.targetPlayerIds[pending.index]),eligible=burningCityEffects(player);if(!player||!eligible.length){if(player)player.fire=Math.max(0,player.fire-6);pending.index+=1;continue;}if(eligible.length===1){const effectIndex=player.effects.findIndex(card=>card.instanceId===eligible[0].instanceId);state.discardPile.push(player.effects.splice(effectIndex,1)[0]);pending.index+=1;continue;}state.currentPlayer=player.playerId;return true;}state.pendingBurningCity=null;return false;}
function resolveBurningCity(state,player,action,sourceIndex){const targetPlayerIds=[...new Set(action.targetPlayerIds??[])],others=state.players.filter(candidate=>candidate.playerId!==player.playerId).map(candidate=>candidate.playerId),required=Math.min(2,others.length);if(targetPlayerIds.length!==required||targetPlayerIds.some(id=>!others.includes(id)))return'Invalid 焚城之火 targets.';state.pendingBurningCity={sourcePlayerId:player.playerId,targetPlayerIds,index:0,resumeFromIndex:sourceIndex};return progressBurningCity(state);}
export function getNormalActions(state){if(state.pendingMissionReward){const entry=state.pendingMissionReward.entries[state.pendingMissionReward.index],player=state.players.find(candidate=>candidate.playerId===entry?.playerId);return player?unfinishedMissionTypes(player).map(recipientPlayerId=>({type:'resolveDivisionRecipient',playerId:player.playerId,recipientPlayerId})):[];}if(state.pendingDivision)return state.pendingDivision.candidatePlayerIds.map(recipientPlayerId=>({type:'resolveDivisionRecipient',playerId:state.pendingDivision.sourcePlayerId,recipientPlayerId}));if(state.pendingRebuild)return rebuildActions(state);if(state.pendingEffectDiscard){const p=state.players.find(c=>c.playerId===state.pendingEffectDiscard.playerId);return p?.hand?.map(card=>({type:'resolveEffectDiscard',playerId:p.playerId,discardInstanceId:card.instanceId}))??[];}if(state.pendingBurningCity){const targetPlayerId=state.pendingBurningCity.targetPlayerIds[state.pendingBurningCity.index],player=state.players.find(candidate=>candidate.playerId===targetPlayerId);return burningCityEffects(player).map(effectInstanceId=>({type:'resolveBurningCityEffectDiscard',playerId:targetPlayerId,targetPlayerId,effectInstanceId:effectInstanceId.instanceId}));}if(!['playing','deathRound'].includes(state.phase)||state.gameOver)return[];const p=state.players.find(c=>c.playerId===state.currentPlayer);if(!p?.hasNormalAction)return[];const plays=blindnessActions(state,p,legalCardActions(state,p)),war=state.phase==='playing'?warActions(state,p):[];if(isDivisionQaSeed(state.qaSeed)&&p.type==='human'&&!state.qaDivisionTriggered)return[...plays,...war,{type:'divisionQaGain',playerId:p.playerId}];if(plays.length||war.length)return[...plays,...war];return[{type:state.phase==='deathRound'?'deathSkip':'redraw',playerId:p.playerId}];}
function nextEligibleIndex(state,from){for(let o=1;o<=state.players.length;o++){const i=(from+state.direction*o+state.players.length)%state.players.length;if(state.players[i].hasNormalAction)return i;}return-1;}function advanceOrSettle(state,from){if(state.pendingMissionReward){state.pendingMissionReward.resumeFromIndex??=from;return state;}if(state.pendingDivision){state.pendingDivision.resumeFromIndex=from;return state;}if(state.pendingEffectDiscard){state.pendingEffectDiscard.resumeFromIndex=from;return state;}if(state.pendingRebuild){state.pendingRebuild.resumeFromIndex=from;return state;}if(state.pendingBurningCity){state.pendingBurningCity.resumeFromIndex=from;return state;}if(state.phase==='deathRound'){state.death.remaining.shift();if(!state.death.remaining.length)return settleRoundMutable(state);state.currentPlayer=state.death.remaining[0];return state;}advanceDeathClock(state,state.players[from]?.playerId??state.currentPlayer);if(state.phase==='deathPending')return state;if(state.players.filter(p=>p.hasNormalAction).length<=1)return settleRoundMutable(state);state.currentPlayer=state.players[nextEligibleIndex(state,from)].playerId;return state;}
function drawWithDiscardRecycle(state,count,ownerId=null){const drawn=[];while(drawn.length<count){if(!state.deck.length){if(!state.discardPile.length)break;const s=shuffleWithState(state.discardPile,state.rngState);state.deck=s.items;state.discardPile=[];state.rngState=s.state;}const card=state.deck.shift();if(isDeathCard(card)){triggerDeath(state,ownerId??state.currentPlayer);continue;}drawn.push(card);}return drawn;}
export function effectChangeAmount(state,amount){const value=Math.max(0,Number(amount)||0),judgment=state.activeJudgments?.['異變'];if(!value)return 0;if(judgment==='overturn-2')return 1;if(judgment==='overturn-1')return Math.min(value,3);return value;}
function triggerDivision(state,sourcePlayer,gained){const judgment=state.activeJudgments?.['資源'];if(!['division-1','division-2'].includes(judgment)||gained<5)return;const eligible=state.players.filter(player=>judgment==='division-2'||player.playerId!==sourcePlayer.playerId),lowest=Math.min(...eligible.map(player=>player.fire)),candidatePlayerIds=eligible.filter(player=>player.fire===lowest).map(player=>player.playerId);state.pendingDivision={sourcePlayerId:sourcePlayer.playerId,candidatePlayerIds,bonus:judgment==='division-1'?2:3,resumeFromIndex:playerIndex(state,sourcePlayer.playerId),judgmentId:judgment};state.currentPlayer=sourcePlayer.playerId;}
function applyEffectFireGain(state,player,amount){const gained=applyMiracleFireGain(player,effectChangeAmount(state,amount));triggerDivision(state,player,gained);return gained;}
function triggerBurningBush(state,player,lost){
  if(!String(state.qaSeed).startsWith('burning-bush-')||lost<=0)return;
  if(state.deferBurningBush){(state.deferredBurningBush??=[]).push({playerId:player.playerId,lost});return;}
  const index=player.effects.findIndex(card=>card.definitionId==='miracle-21');
  if(index<0)return;
  const [card]=player.effects.splice(index,1);state.discardPile.push(card);
  const gain=applyEffectFireGain(state,player,Math.min(4,Math.floor(lost/2)));
  state.lastBurningBush={playerId:player.playerId,lost,gain};
}
export function finishDeferredBurningBush(state,actualLosses={}){const events=state.deferredBurningBush??[];delete state.deferredBurningBush;delete state.deferBurningBush;for(const event of events){const player=state.players.find(p=>p.playerId===event.playerId);if(player)triggerBurningBush(state,player,actualLosses[event.playerId]??event.lost);}}
function drawByEffect(state,player,count){const dawn=player.effects.find(e=>e.definitionId==='miracle-13'),drawn=drawWithDiscardRecycle(state,effectChangeAmount(state,count+(dawn?1:0)),player.playerId);player.hand.push(...drawn);if(dawn&&drawn.length){state.pendingEffectDiscard={playerId:player.playerId,effectInstanceId:dawn.instanceId,resumeFromIndex:null};}return drawn;}
function drawByWar(state,player,count){const dawn=player.effects.find(e=>e.definitionId==='miracle-13'),drawn=drawWithDiscardRecycle(state,count+(dawn?effectChangeAmount(state,1):0),player.playerId);player.hand.push(...drawn);if(dawn&&drawn.length)state.pendingEffectDiscard={playerId:player.playerId,effectInstanceId:dawn.instanceId,resumeFromIndex:null};return drawn;}
function consumeEffects(state,player,ids){const consumed=[];player.effects=player.effects.filter(e=>{if(!ids.includes(e.definitionId))return true;consumed.push(e);return false;});state.discardPile.push(...consumed);}
function nextSeatIndex(state,from){return(from+state.direction+state.players.length)%state.players.length;}
function transferPlagueAfterSheep(state,playerIndexValue){const player=state.players[playerIndexValue],plagues=player.effects.filter(e=>e.definitionId==='disaster-09');if(!plagues.length)return;player.effects=player.effects.filter(e=>e.definitionId!=='disaster-09');const next=state.players[nextSeatIndex(state,playerIndexValue)];next.effects.push(...plagues.map(card=>({...card,effectOwnerPlayerId:next.playerId})));}
function expireRoundEffects(state){for(const player of state.players){const expiring=[],remaining=[];for(const card of player.effects){if(getDefinition(card).duration==='round')expiring.push(card);else remaining.push(card);}player.effects=remaining;state.discardPile.push(...expiring);}}
function applyCardCorruption(state,definition){const amount=getCardCorruption(definition);if(!amount)return;state.corruption=(state.corruption??0)+amount;while(state.corruption>=state.corruptionThreshold&&state.judgmentDeck.length){state.corruption-=state.corruptionThreshold;const judgmentId=state.judgmentDeck.shift(),judgment=getJudgmentDefinition(judgmentId),replacedJudgmentId=state.activeJudgments[judgment.domain]??null;state.activeJudgments[judgment.domain]=judgment.id;if(judgment.upgradesTo&&!state.judgmentDeck.includes(judgment.upgradesTo)){const shuffled=shuffleWithState([...state.judgmentDeck,judgment.upgradesTo],state.rngState);state.judgmentDeck=shuffled.items;state.rngState=shuffled.state;}const entry={judgmentId:judgment.id,domain:judgment.domain,replacedJudgmentId,round:state.round};state.judgmentHistory.push(entry);state.lastJudgment=entry;}}
function playResourceMutable(state,action){const index=playerIndex(state,action.playerId),player=state.players[index],handIndex=player.hand.findIndex(c=>c.instanceId===action.instanceId);if(handIndex<0)return{error:'Card is not in the current player hand.'};const card=player.hand[handIndex];if(!isResourceLegalForPlayer(card,state,player,action.declaredType))return{error:'Illegal resource play.'};const d=getDefinition(card),playedCard={...card,declaredType:d.type==='grace'?action.declaredType:d.type},profile=resourceNumberProfile(player,card,playedCard.declaredType);player.hand.splice(handIndex,1);state.playedArea.push(playedCard);applyCardCorruption(state,d);addMissionProgress(player,playedCard.declaredType,profile.baseNumber);state.currentResource={type:playedCard.declaredType,number:profile.number,instanceId:card.instanceId,baseNumber:profile.baseNumber,numberBonus:profile.numberBonus,numberPenalty:profile.numberPenalty,numberModifier:profile.numberModifier};state.currentApostle=player.playerId;consumeEffects(state,player,['miracle-02','miracle-03']);if(playedCard.declaredType==='sheep'&&profile.numberPenalty)transferPlagueAfterSheep(state,index);return{state:advanceOrSettle(state,index)};}
function resolveWindMiracle(state,player,action){const choice=action.choice??'fire';if(choice==='fire'){applyEffectFireGain(state,player,4);return null;}if(choice!=='cycle')return'Unknown 如風吹來 choice.';const ids=[...new Set(action.discardIds??[])];if(ids.length<1||ids.length>3)return'如風吹來 must discard 1 to 3 cards.';const selected=ids.map(id=>player.hand.find(c=>c.instanceId===id));if(selected.some(c=>!c))return'A selected discard card is not in hand.';const changed=selected.slice(0,effectChangeAmount(state,selected.length));player.hand=player.hand.filter(c=>!changed.some(selectedCard=>selectedCard.instanceId===c.instanceId));state.discardPile.push(...changed);drawByEffect(state,player,changed.length);return null;}
function resolveRebirth(state,player){const count=effectChangeAmount(state,player.hand.length);if(!count)return null;const changed=player.hand.slice(0,count);state.discardPile.push(...changed);player.hand=player.hand.slice(count);drawByEffect(state,player,count);return null;}
function putBottomRandom(state,cards){const shuffled=shuffleWithState(cards,state.rngState);state.rngState=shuffled.state;state.deck.push(...shuffled.items);}
function resolveHopeInsight(state,player,action){let count=0;for(const card of state.deck.slice(0,3)){if(isDeathCard(card))break;count+=1;}if(count===0)return null;const viewed=state.deck.splice(0,count),selectedId=action.selectedCardId??viewed[0].instanceId,selected=viewed.find(c=>c.instanceId===selectedId);if(!selected)return'所望之實底 must select one of the viewed cards.';player.hand.push(selected);putBottomRandom(state,viewed.filter(c=>c.instanceId!==selectedId));return null;}
function insightCardType(card){return isDeathCard(card)?'death':getDefinition(card).kind;}
function deepInsightRevealCount(state){const seen=new Set();let count=0;for(const card of state.deck.slice(0,5)){if(isDeathCard(card))break;count+=1;seen.add(insightCardType(card));if(seen.size>=3)break;}return count;}
function resolveDeepInsight(state,player,action){const count=deepInsightRevealCount(state),deathRevealed=Boolean(state.deck[count]&&isDeathCard(state.deck[count])),viewed=state.deck.splice(0,count);if(deathRevealed){state.deck.shift();putBottomRandom(state,viewed);triggerDeath(state,player.playerId);return null;}if(!viewed.length)return null;const selectedId=action.selectedCardId??viewed[0].instanceId,selected=viewed.find(c=>c.instanceId===selectedId);if(!selected)return'行向水深之處 must select one of the revealed cards.';player.hand.push(selected);putBottomRandom(state,viewed.filter(c=>c.instanceId!==selectedId));return null;}
function singleTargetDisasterRecipients(state,target){if(state.activeJudgments?.['災變']!=='sinking-1')return[target];const targetIndex=playerIndex(state,target.playerId),neighbors=[-1,1].map(offset=>state.players[(targetIndex+offset+state.players.length)%state.players.length]);return[...new Map([target,...neighbors].map(player=>[player.playerId,player])).values()];}
function resolveTreasureDisaster(state,player,action){if(!action.targetPlayerId)return'積財寶在地上 requires a target.';if(action.targetPlayerId===player.playerId&&!action.reactionRedirect)return'積財寶在地上 must target another player.';const target=state.players.find(p=>p.playerId===action.targetPlayerId);if(!target)return'Unknown target player.';for(const recipient of singleTargetDisasterRecipients(state,target)){const before=recipient.fire;recipient.fire=Math.max(0,recipient.fire-effectChangeAmount(state,Math.min(Math.floor(recipient.fire/5)*2,12)));triggerBurningBush(state,recipient,before-recipient.fire);}return null;}
function resolvePlague(state,player,card,action){const target=state.players.find(p=>p.playerId===action.targetPlayerId);if(!target)return'瘟疫 requires a target player.';target.effects.push({...card,effectSourcePlayerId:player.playerId,effectOwnerPlayerId:target.playerId});return null;}
function resolveRainCover(state,action){const target=state.players.find(p=>p.playerId===action.targetPlayerId);if(!target)return'雨幕之下 requires a target player.';const eligible=getCleanseableEffects(target);if(!eligible.length)return null;const selectedId=action.effectInstanceId??eligible[0].instanceId;if(!eligible.some(card=>card.instanceId===selectedId))return'雨幕之下 must choose a persistent disaster or negative effect from the target effect zone.';const removed=removeEffectByInstanceId(state,target,selectedId);if(removed)applyEffectFireGain(state,target,2);return null;}
function resolveInsectSwarm(state,player,card,action){const target=state.players.find(candidate=>candidate.playerId===action.targetPlayerId);if(!target||target.playerId===player.playerId)return'蟲災 requires one other player.';target.effects.push({...card,effectSourcePlayerId:player.playerId,effectOwnerPlayerId:target.playerId});return null;}
function exchangeType(card){const d=getDefinition(card);if(d.kind!=='resource')return d.kind;return d.type==='grace'?(card.declaredType||'grace'):d.type;}
function resolveBirdExchange(state,player,action){const target=state.players.find(p=>p.playerId===action.targetPlayerId);if(!target||target.playerId===player.playerId)return'恰如飛鳥經過 requires another player.';if(!player.hand.length||!target.hand.length)return'Both players need a hand card.';const ownId=action.selectedOwnCardId??player.hand[0]?.instanceId,targetId=action.targetCardId??target.hand[0].instanceId,ownIndex=player.hand.findIndex(c=>c.instanceId===ownId),targetIndex=target.hand.findIndex(c=>c.instanceId===targetId);if(ownIndex<0||targetIndex<0)return'Invalid exchange card selection.';if(action.consent===false)return null;const own=player.hand[ownIndex],theirs=target.hand[targetIndex];player.hand[ownIndex]=theirs;target.hand[targetIndex]=own;if(exchangeType(own)!==exchangeType(theirs))queueMissionReward(state,[player.playerId,target.playerId],2,{resumeFromIndex:playerIndex(state,player.playerId)});return null;}
function resolveLiesAndTemptation(state,player,action){const ids=[...new Set(action.targetPlayerIds??[])];if(ids.length!==2||(!action.reactionRedirect&&ids.includes(player.playerId)))return'謊言與試探 requires two other players.';const targets=ids.map(id=>state.players.find(p=>p.playerId===id));if(targets.some(p=>!p||!p.hand.length))return'Both targets need at least one hand card.';const revealed=targets.map((p,i)=>p.hand.find(c=>c.instanceId===(action.targetCardIds?.[i]??p.hand[0].instanceId)));if(revealed.some(c=>!c))return'Invalid revealed card.';const chosenId=action.chosenCardId??revealed[0].instanceId,chosenIndex=revealed.findIndex(c=>c.instanceId===chosenId);if(chosenIndex<0)return'Chosen card must be one of the two revealed cards.';const owner=targets[chosenIndex],handIndex=owner.hand.findIndex(c=>c.instanceId===chosenId);player.hand.push(owner.hand.splice(handIndex,1)[0]);return null;}
