function defaultArkChoice(state,player){const resources=resourceCards(player);if(!resources.length)return{keepType:null,discardIds:[]};const counts=Object.fromEntries(RESOURCE_TYPES.map(t=>[t,resources.filter(c=>getDefinition(c).type===t).length]));const keepType=RESOURCE_TYPES.toSorted((a,b)=>counts[b]-counts[a])[0],eligible=resources.filter(c=>getDefinition(c).type!==keepType);return{keepType,discardIds:eligible.slice(0,effectChangeAmount(state,Math.min(2,eligible.length))).map(c=>c.instanceId)};}
function resolveOutsideArk(state,action){const choices=action.groupChoices??{};for(const p of state.players){const resources=resourceCards(p);if(!resources.length)continue;const choice=choices[p.playerId]??defaultArkChoice(state,p),availableTypes=[...new Set(resources.map(c=>getDefinition(c).type))];if(!RESOURCE_TYPES.includes(choice.keepType)||!availableTypes.includes(choice.keepType))return`方舟之外 requires ${p.playerId} to keep a resource type.`;const eligible=resources.filter(c=>getDefinition(c).type!==choice.keepType),required=effectChangeAmount(state,Math.min(2,eligible.length)),ids=[...new Set(choice.discardIds??[])];if(ids.length!==required||ids.some(id=>!eligible.some(c=>c.instanceId===id)))return`Invalid 方舟之外 discard choice for ${p.playerId}.`;const discarded=p.hand.filter(c=>ids.includes(c.instanceId));p.hand=p.hand.filter(c=>!ids.includes(c.instanceId));state.discardPile.push(...discarded);}return null;}
