function resolveRebuildInitialDiscardMutable(state,action){const pending=state.pendingRebuild;if(!pending||pending.stage!=='discardInitial'||pending.playerId!==action.playerId)return{error:'No 拆毀後重建 initial discard is pending.'};const player=state.players.find(p=>p.playerId===action.playerId),index=player.hand.findIndex(c=>c.instanceId===action.discardInstanceId);if(index<0)return{error:'Selected initial discard is not in hand.'};state.discardPile.push(player.hand.splice(index,1)[0]);pending.viewedIds=state.discardPile.slice(-5).map(c=>c.instanceId);if(!pending.viewedIds.length)return{state:finishRebuild(state)};pending.stage='chooseDiscard';return{state};}
